class Solution {
public:
    int longestSquareStreak(std::vector<int>& nums) {
        std::unordered_set<long long> s(nums.begin(), nums.end());
        int ans = -1;
        for (long long x : nums) {
            int len = 0;
            long long cur = x;
            while (s.count(cur)) {
                len++;
                cur = cur * cur;
                if (cur > 100000) break;
            }
            if (len >= 2) ans = std::max(ans, len);
        }
        return ans;
    }
};

class Solution {
    public int longestSquareStreak(int[] nums) {
        java.util.Set<Long> set = new java.util.HashSet<>();
        for (int x : nums) set.add((long)x);
        int ans = -1;
        for (int x : nums) {
            int len = 0;
            long cur = x;
            while (set.contains(cur)) {
                len++;
                cur = cur * cur;
                if (cur > 100000) break;
            }
            if (len >= 2) ans = Math.max(ans, len);
        }
        return ans;
    }
}

var longestSquareStreak = function(nums) {
    const set = new Set(nums);
    let ans = -1;
    for (const x of nums) {
        let len = 0;
        let cur = x;
        while (set.has(cur)) {
            len++;
            cur = cur * cur;
            if (cur > 100000) break;
        }
        if (len >= 2 && len > ans) ans = len;
    }
    return ans;
};
